    // Initialize chain
    Chain = new Array[ChainLength]
    Chain[0] = InitialInput

    // Compute chain steps
    for (j = 1; j < ChainLength; j++) {
        // Perform hash and reduction
        Chain[j] = Reduce(Hash(Chain[j-1]))
    }

    // Store final hash in Rainbow Table
    RainbowTable[i] = Chain[ChainLength-1]
}

// During attack, compare stored hash against Rainbow Table
